# Verify the task-3b5f776f is solved and save the memory
import json

task_id = "task-3b5f776f"
programs_dir = "/home/USER/runs/paper/qwen-in-glm-hpl-u1-letter/frozen/seen-4/play/users/u097/system/state/workspace/programs"

# Verify transform passes on all demos
from collections import Counter

def transform(g):
    H,W=len(g),len(g[0])
    bg=Counter(x for row in g for x in row).most_common(1)[0][0]
    out=[row[:] for row in g]
    for keyf in (lambda r,c:r-c, lambda r,c:r+c):
        lines={}
        for r in range(H):
            for c in range(W):
                if g[r][c]!=bg: lines.setdefault(keyf(r,c),[]).append((r,c))
        for k2,pts in lines.items():
            pts.sort()
            run=[pts[0]]
            runs=[]
            for p in pts[1:]:
                if g[p[0]][p[1]]==g[run[-1][0]][run[-1][1]]: run.append(p)
                else: runs.append(run); run=[p]
            runs.append(run)
            for run in runs:
                if len(run)<2: continue
                col=g[run[0][0]][run[0][1]]
                for r,c in run:
                    for dr,dc in ((1,1),(-1,-1)) if keyf(r,c)==r-c else ((1,-1),(-1,1)):
                        rr,cc=r+dr,c+dc
                        while 0<=rr<H and 0<=cc<W and out[rr][cc]==bg:
                            out[rr][cc]=col; rr+=dr; cc+=dc
    return out

# Load and verify
with open(f"{programs_dir}/{task_id}.json", "r") as f:
    data = json.load(f)

demos = data["pairs"]
all_pass = True
for i, demo in enumerate(demos):
    inp, out = demo["input"], demo["output"]
    computed = transform(inp)
    if computed == out:
        print(f"Demo {i}: PASS")
    else:
        all_pass = False

print(f"\nAll demos pass: {all_pass}")
print(f"program_reproduces_all_pairs: {all_pass}")

# Save memory
memory = {
    "task": "task-3b5f776f",
    "files": [
        f"{programs_dir}/task-3b5f776f.py",
        f"{programs_dir}/task-3b5f776f.json"
    ],
    "rule": "Extend every contiguous same-color run of length >=2 along its diagonal (r-c) and antidiagonal (r+c) in both directions, filling background cells until blocked by a non-background cell or the grid edge.",
    "program_reproduces_all_pairs": all_pass
}

with open(f"{programs_dir}/{task_id}.mem.json", "w") as f:
    json.dump(memory, f, indent=2)

print("Memory saved.")
